css:
.sb2063-container{--sb-ink:#0d1b2a;--sb-snow:#e8f1f8;--sb-blue:#1f6f9e;--sb-deep:#134a6b;--sb-water:#3aa8c1;--sb-cash:#2f8f5b;--sb-warn:#a9540f;--sb-bad:#a33017;--sb-rule:#d5e0e8;--sb-muted:#52626f;font-family:"Segoe UI",system-ui,-apple-system,sans-serif;color:var(--sb-ink);max-width:1080px;margin:0 auto;padding:4px 2px 32px}
.sb2063-header{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;border-bottom:3px solid var(--sb-deep);padding-bottom:10px;margin-bottom:16px}
.sb2063-brand h1{margin:0;font-size:1.85rem;letter-spacing:-.02em;font-weight:700}
.sb2063-sub{margin:2px 0 0;color:var(--sb-muted);font-size:.93rem}
.sb2063-clock{text-align:right;font-size:.9rem;color:var(--sb-muted)}
.sb2063-clock strong{display:block;font-size:1.3rem;color:var(--sb-deep)}
.sb2063-month{display:block;font-size:.85rem;font-style:italic}
.sb2063-gauges{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px}
.sb2063-gauge{background:var(--sb-snow);border-radius:10px;padding:10px 12px}
.sb2063-gauge-label{display:block;font-size:.76rem;color:var(--sb-muted);margin-bottom:6px}
.sb2063-gauge strong{display:block;margin-top:5px;font-size:1.05rem;color:var(--sb-deep)}
.sb2063-bar{height:9px;background:#fff;border-radius:6px;overflow:hidden}
.sb2063-bar-fill{height:100%;width:0;border-radius:6px;transition:width .5s ease}
.sb2063-snow{background:linear-gradient(90deg,#9fc7e0,#1f6f9e)}
.sb2063-water{background:linear-gradient(90deg,#8fd6e4,#3aa8c1)}
.sb2063-made{background:linear-gradient(90deg,#c9d6f2,#5b78c7)}
.sb2063-sat{background:linear-gradient(90deg,#f0c48b,#c46a1c)}
.sb2063-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}
.sb2063-kpi{border:1px solid var(--sb-rule);border-radius:10px;padding:10px 12px;background:#fff}
.sb2063-kpi span{display:block;font-size:.76rem;color:var(--sb-muted)}
.sb2063-kpi strong{display:block;font-size:1.22rem;margin-top:3px;color:var(--sb-ink)}
.sb2063-kpi-target{background:#fbf5ec;border-color:#e8d2b4}
.sb2063-kpi-target strong{color:var(--sb-warn)}
.sb2063-neg{color:var(--sb-bad)!important}
.sb2063-brief{background:#fff;border-left:4px solid var(--sb-blue);padding:11px 14px;border-radius:0 8px 8px 0;margin-bottom:16px;font-size:.93rem;line-height:1.5;box-shadow:0 1px 4px rgba(13,27,42,.07)}
.sb2063-card{display:none;border:1px solid var(--sb-rule);border-radius:12px;padding:14px 18px;margin-bottom:16px;background:#fff}
.sb2063-card.sb2063-on{display:block}
.sb2063-card h2{margin:0 0 8px;font-size:1.05rem;color:var(--sb-deep)}
.sb2063-card h3{margin:14px 0 6px;font-size:.92rem;color:var(--sb-deep)}
.sb2063-wx{background:#f6fafd}
.sb2063-wx p{margin:0 0 8px;font-size:.88rem;line-height:1.5}
.sb2063-wxrow{display:grid;grid-template-columns:minmax(150px,1.4fr) 2fr 52px minmax(120px,1.2fr);gap:8px;align-items:center;font-size:.84rem;padding:4px 0;border-bottom:1px dashed var(--sb-rule)}
.sb2063-wxrow:last-child{border-bottom:0}
.sb2063-wxname{font-weight:600}
.sb2063-wxbar{height:10px;background:#fff;border:1px solid var(--sb-rule);border-radius:6px;overflow:hidden}
.sb2063-wxbar i{display:block;height:100%;background:var(--sb-blue)}
.sb2063-wxpct{font-weight:700;color:var(--sb-deep);text-align:right}
.sb2063-wxfig{color:var(--sb-muted);font-size:.8rem}
.sb2063-range{display:flex;flex-wrap:wrap;gap:10px;margin:10px 0 4px}
.sb2063-chip{background:#fff;border:1px solid var(--sb-rule);border-radius:9px;padding:7px 11px;font-size:.84rem}
.sb2063-chip b{display:block;font-size:1.02rem;color:var(--sb-deep)}
.sb2063-wx-buy{display:none;margin-top:10px;align-items:center;gap:12px;flex-wrap:wrap}
.sb2063-wx-buy.sb2063-on{display:flex}
.sb2063-note{font-size:.79rem;color:var(--sb-muted);line-height:1.4}
.sb2063-panel{display:none;border:1px solid var(--sb-rule);border-radius:12px;padding:16px 18px;margin-bottom:16px;background:#fff}
.sb2063-panel.sb2063-on{display:block}
.sb2063-panel h2{margin:0 0 5px;font-size:1.12rem;color:var(--sb-deep)}
.sb2063-help{margin:0 0 14px;font-size:.88rem;color:var(--sb-muted);line-height:1.5}
.sb2063-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px}
.sb2063-field{display:flex;flex-direction:column;font-size:.85rem;gap:5px}
.sb2063-field>label{font-weight:600}
.sb2063-field input[type=number],.sb2063-field select{padding:7px 9px;border:1px solid #9fb2c0;border-radius:7px;font-size:.92rem;background:#fff;color:var(--sb-ink)}
.sb2063-field input[type=range]{width:100%}
.sb2063-field output{font-weight:700;color:var(--sb-deep)}
.sb2063-check{flex-direction:row;align-items:flex-start;gap:8px}
.sb2063-check input{margin-top:3px}
.sb2063-check>label{font-weight:500}
.sb2063-budget{margin:12px 0 4px;padding:9px 12px;border-radius:8px;background:var(--sb-snow);font-size:.88rem;font-weight:600}
.sb2063-budget.sb2063-over{background:#fbe6e2;color:var(--sb-bad)}
.sb2063-sys{margin:8px 0 14px;padding:10px 12px;border-radius:8px;border:1px dashed #9fb2c0;font-size:.85rem;line-height:1.55;background:#fbfdff}
.sb2063-sys b{color:var(--sb-deep)}
.sb2063-sys .sb2063-flag{color:var(--sb-warn);font-weight:600}
.sb2063-actions{text-align:right;margin:18px 0}
.sb2063-actions.sb2063-off{display:none}
.sb2063-btn{background:var(--sb-deep);color:#fff;border:0;border-radius:9px;padding:11px 26px;font-size:.98rem;font-weight:600;cursor:pointer}
.sb2063-btn:hover{background:var(--sb-blue)}
.sb2063-btn:disabled{opacity:.45;cursor:not-allowed}
.sb2063-btn-ghost{background:#fff;color:var(--sb-deep);border:2px solid var(--sb-deep);border-radius:9px;padding:8px 16px;font-size:.88rem;font-weight:600;cursor:pointer}
.sb2063-btn-ghost:hover{background:var(--sb-snow)}
.sb2063-btn-ghost:disabled{opacity:.5;cursor:not-allowed}
.sb2063-container :focus-visible{outline:3px solid #e08a1e;outline-offset:2px}
.sb2063-report{border-left:4px solid var(--sb-cash)}
.sb2063-rgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:6px 22px}
.sb2063-rline{display:flex;justify-content:space-between;gap:10px;font-size:.85rem;padding:3px 0;border-bottom:1px dotted var(--sb-rule)}
.sb2063-rline span{color:var(--sb-muted)}
.sb2063-rline b{white-space:nowrap}
.sb2063-rline.sb2063-total{border-bottom:0;border-top:2px solid var(--sb-rule);font-size:.92rem;margin-top:2px}
.sb2063-rline.sb2063-total span{color:var(--sb-ink);font-weight:600}
.sb2063-limit{display:inline-block;padding:1px 8px;border-radius:10px;font-size:.76rem;font-weight:700;background:var(--sb-snow);color:var(--sb-deep)}
.sb2063-limit.sb2063-hot{background:#fbe6e2;color:var(--sb-bad)}
.sb2063-coach{margin-top:12px;padding:10px 12px;border-radius:8px;background:#fbf5ec;font-size:.88rem;line-height:1.5}
.sb2063-final{border-left:4px solid var(--sb-warn)}
.sb2063-tier{font-size:1.3rem;font-weight:700;color:var(--sb-deep);margin:0 0 4px}
.sb2063-score{font-size:.95rem;color:var(--sb-muted);margin:0 0 10px}
.sb2063-final ul{margin:6px 0 0;padding-left:20px;font-size:.88rem;line-height:1.55}
.sb2063-charts{margin:20px 0}
.sb2063-chart-box{border:1px solid var(--sb-rule);border-radius:12px;padding:12px;background:#fff}
.sb2063-history h3{font-size:1rem;color:var(--sb-deep);margin:0 0 8px}
.sb2063-table-wrap{overflow-x:auto}
.sb2063-history table{width:100%;border-collapse:collapse;font-size:.86rem}
.sb2063-history th,.sb2063-history td{padding:7px 9px;border-bottom:1px solid var(--sb-rule);text-align:right}
.sb2063-history th:first-child,.sb2063-history td:first-child{text-align:left}
.sb2063-history th{color:var(--sb-muted);font-weight:600}
@media (max-width:720px){.sb2063-gauges,.sb2063-kpis{grid-template-columns:repeat(2,1fr)}.sb2063-header{flex-direction:column;align-items:flex-start}.sb2063-clock{text-align:left}.sb2063-wxrow{grid-template-columns:1fr 1fr 44px}.sb2063-wxfig{grid-column:1 / -1}}
@media (prefers-reduced-motion:reduce){.sb2063-bar-fill{transition:none}}

