                C: { prob: 0.25, thawP: 0.35, nat: [0, 0, 0.18, 0.70, 0.88, 0.50], cold: [0, 0, 6, 18, 22, 3],  melt: [0, 0, 0.30, 0.10, 0.15, 0.45], dem: [0, 0, 0.88, 0.97, 1.00, 1.00], storm: [0, 0, 0, 1, 1, 0], hard: [0, 0, 1.6, 1.0, 0.95, 1.2] },
                D: { prob: 0.20, thawP: 0.65, nat: [0, 0, 0.25, 0.50, 0.62, 0.30], cold: [0, 0, 7, 12, 11, 1],  melt: [0, 0, 0.22, 0.25, 0.30, 0.60], dem: [0, 0, 0.94, 0.94, 0.95, 0.92], storm: [0, 0, 0, 0, 0, 0], hard: [0, 0, 1.5, 1.3, 1.4, 1.6] }
            };
            this.TYPES = ['A', 'B', 'C', 'D'];

            // The prudent reference plan. Its EBITDA in THIS game's winter is the par a run is measured against.
            this.PAR_PLAN = [null,
                { sbInvSnow: 1.5, sbInvLift: 2.5, sbInvAccess: 2.0, sbPassPrice: 500, sbStaff: 320 },
                { sbSnowDays: 8, sbPriceDec: 48, sbExtraStaffDec: 0 },
                { sbSnowDaysJan: 1, sbPriceMid: 30, sbPriceWknd: 50, sbSectorsJan: 3, sbPacks: 2 },
                { sbSnowDaysFeb: 2, sbCap: 10, sbPeak: 20, sbHighSector: 1, sbQueue: 0 },
                { sbSummer: 1, sbRisk: 'snow' }];
            this._bound = false;
        }

        // ── lifecycle (kept short and quote-free on purpose: importer body extractor) ──
        initialize(state) {
            state.domainState = this._seed(state, state.domainState || {});
            state.decisions = this._decObj(state.decisions);
            this._later();
        }

        validateDecisions() {
            return this._check();
        }

        calculateResults(state) {
            return this._closePeriod(state);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            this._wire();
            this._bindRepaint();
            this._later();
        }

        // ── small helpers ────────────────────────────────────────────────
        _sim() { return window.mySimulation || null; }
        _state() { const s = this._sim(); return s ? s.state : null; }
        _t(k, vars) { try { return this._sim().t(k, vars); } catch (e) { return k; } }
        _el(id) { return document.getElementById(id); }
        _clone(o) { return JSON.parse(JSON.stringify(o)); }
        _clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
        _period(state) { return this._clamp(parseInt(state.currentPeriod, 10) || 1, 1, 5); }

        _lang() {
            const norm = function (v) { return String(v).split('-')[0].toLowerCase(); };
            try {
                if (window.vcI18n && window.vcI18n._lang) return norm(window.vcI18n._lang);
                if (document.documentElement && document.documentElement.lang) return norm(document.documentElement.lang);
            } catch (e) { }
            return 'en';
        }
        _loc() { const l = this._lang(); return l === 'ca' ? 'ca-ES' : (l === 'es' ? 'es-ES' : 'en-GB'); }
        _n(v, d) { d = d || 0; return Number(v || 0).toLocaleString(this._loc(), { minimumFractionDigits: d, maximumFractionDigits: d, useGrouping: 'always' }); }
        _eur(v) { return this._n(Math.round(v || 0)).replace(/^-/, '−') + ' €'; }
        // the platform can hand back decisions as a JSON array; string keys on an array never serialise
        _decObj(d) { return (d && typeof d === 'object') ? Object.assign({}, d) : {}; }
        _meur(v) { return this._n((v || 0) / 1e6, 2) + ' M€'; }
        _pct(v) { return this._n((v || 0) * 100) + ' %'; }

        _num(id, dflt) {
            const e = this._el(id);
            if (!e) return dflt;
            let v = parseFloat(e.value);
            if (isNaN(v)) v = dflt;
            const lo = parseFloat(e.getAttribute('min')), hi = parseFloat(e.getAttribute('max'));
            if (!isNaN(lo)) v = Math.max(lo, v);
            if (!isNaN(hi)) v = Math.min(hi, v);
            return v;
        }
        _chk(id) { const e = this._el(id); return !!(e && e.checked); }
        _sel(id, dflt) { const e = this._el(id); return (e && e.value !== '' && e.value != null) ? e.value : dflt; }

        // Seeded generator: every team in the same game gets the same winter.
        _rng(str) {
            let h = 2166136261;
            for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
            let a = h >>> 0;
            return function () {
                a = (a + 0x6D2B79F5) >>> 0;
                let t = a;
                t = Math.imul(t ^ (t >>> 15), t | 1);
                t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
                return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
            };
        }

        _buildWeather(seedStr) {
            const cfg = (typeof window.engineConfig === 'object' && window.engineConfig) ? window.engineConfig : {};
            const rnd = this._rng('sb2063:' + (cfg.seed || seedStr));
            let type = 'D', acc = 0;
            const u = rnd();
            for (let i = 0; i < this.TYPES.length; i++) { acc += this.ARCH[this.TYPES[i]].prob; if (u < acc) { type = this.TYPES[i]; break; } }
            let jitter = true;
            if (cfg.weather && this.ARCH[cfg.weather]) { type = cfg.weather; jitter = false; }
            const a = this.ARCH[type];
            const thawDraw = rnd();
            const wx = { type: type, nat: [0, 0], cold: [0, 0], melt: a.melt.slice(), dem: a.dem.slice(), storm: a.storm.slice(), hard: a.hard.slice(), fcN: [0, 0], fcC: [0, 0] };
            for (let p = 2; p <= 5; p++) {
                const jn = jitter ? (rnd() * 2 - 1) * 0.05 : 0;
                const jc = jitter ? Math.round((rnd() * 2 - 1) * 2) : 0;
                wx.nat[p] = Math.round(this._clamp(a.nat[p] + jn, 0.05, 1) * 100) / 100;
                wx.cold[p] = Math.max(0, a.cold[p] + jc);
                // monthly forecast: a range that always contains the truth, never centred on it
                const e1 = 1 + Math.floor(rnd() * 3), e2 = 1 + Math.floor(rnd() * 3);
                wx.fcC[p] = [Math.max(0, wx.cold[p] - e1), wx.cold[p] + e2];
                const n1 = 0.04 + rnd() * 0.07, n2 = 0.04 + rnd() * 0.07;
                wx.fcN[p] = [Math.round(this._clamp(wx.nat[p] - n1, 0, 1) * 100) / 100, Math.round(this._clamp(wx.nat[p] + n2, 0, 1) * 100) / 100];
            }
            // specialist seasonal forecast: right about the winter type fcAccuracy of the time
            const others = this.TYPES.filter(function (x) { return x !== type; });
            wx.signal = (rnd() < this.K.fcAccuracy) ? type : others[Math.floor(rnd() * others.length)];
            wx.thaw = jitter ? (thawDraw < a.thawP ? 1 : 0) : ((cfg.thaw === 0 || cfg.thaw === 1) ? cfg.thaw : (a.thawP > 0.5 ? 1 : 0));
            return wx;
        }

        _seed(state, ds) {
            const K = this.K;
            if (!ds.wx) {
                let seed = state && state.gameId ? String(state.gameId) : '';
                if (!seed) { ds.seed = ds.seed || String(Math.floor(Math.random() * 1e9)); seed = ds.seed; }
                ds.wx = this._buildWeather(seed);
            }
            if (!ds.c) {
                ds.c = {
                    water: this.WATER0, made: 0, cov: 0.38, rate: 1, nights: 1, eff: 1, liftCap: K.liftBase, accessCap: K.accessBase, clearing: 0,
                    invSnow: 0, invLift: 0, invAccess: 0, passSold: 0, passPrice: K.passRef, staff: 340, fc: 0,
                    sat: K.satStart, cash: K.cash0, rev: 0, ebitda: 0, skier: 0, open: 0,
                    snowSpend: 0, peakRev: 0, seasonRev: 0, natW: 0, summer: null, risk: null, fiveYear: 0
                };
            }
            ds.at = ds.at || {};
            return ds;
        }

        // ── decisions ────────────────────────────────────────────────────
        _readDecisions(p, ds) {
            const d = {};
            if (p === 1) {
                d.sbInvSnow = this._num('sbInvSnow', 0); d.sbInvLift = this._num('sbInvLift', 0); d.sbInvAccess = this._num('sbInvAccess', 0);
                d.sbPassPrice = this._num('sbPassPrice', 560); d.sbStaff = this._num('sbStaff', 340);
            } else if (p === 2) {
                d.sbSnowDays = this._num('sbSnowDays', 0); d.sbPriceDec = this._num('sbPriceDec', 47); d.sbExtraStaffDec = this._chk('sbExtraStaffDec') ? 1 : 0;
            } else if (p === 3) {
                d.sbSnowDaysJan = this._num('sbSnowDaysJan', 0); d.sbPriceMid = this._num('sbPriceMid', 41); d.sbPriceWknd = this._num('sbPriceWknd', 49);
                d.sbSectorsJan = parseInt(this._sel('sbSectorsJan', '3'), 10) || 3; d.sbPacks = this._num('sbPacks', 1);
            } else if (p === 4) {
                d.sbSnowDaysFeb = this._num('sbSnowDaysFeb', 0); d.sbCap = this._num('sbCap', 10); d.sbPeak = this._num('sbPeak', 10);
                d.sbHighSector = this._chk('sbHighSector') ? 1 : 0; d.sbQueue = this._chk('sbQueue') ? 1 : 0;
            } else {
                d.sbSummer = parseInt(this._sel('sbSummer', '0'), 10) || 0; d.sbRisk = this._sel('sbRisk', 'snow');
            }
            return d;
        }

        _invTotal() { return this._num('sbInvSnow', 0) + this._num('sbInvLift', 0) + this._num('sbInvAccess', 0); }

        _check() {
            const st = this._state();
            const p = st ? this._period(st) : 1;
            if (p === 1) {
                const total = this._invTotal();
                if (total > this.BUDGET + 1e-9) { this._warn(this._t('warn_budget')); return false; }
                if (total < 0.5 - 1e-9) { this._warn(this._t('warn_budget_min')); return false; }
            }
            return true;
        }
        _warn(msg) { try { this._sim().uiManager.showNotification(msg, 'warning'); } catch (e) { } }

        // ── the round: pure function of (period, carry, decisions, weather) ──
        _closePeriod(state) {
            const ds = state.domainState = this._seed(state, state.domainState || {});
            const p = this._period(state);
            const dec = this._readDecisions(p, ds);
            const c0 = ds.at[p] ? this._clone(ds.at[p]) : this._clone(ds.c);
            if (ds.c && ds.c.fc) c0.fc = 1;
            ds.at[p] = this._clone(c0);
            const out = this._computeRound(p, c0, dec, ds.wx);
            ds.c = out.c;
            const v = out.results.final || this._verdict(out.c, ds.wx, p);
            ds.performance = { overallScore: v.score, band: v.tier, parRatio: v.parRatio, period: p };
            out.results.overallScore = v.score;
            state.decisions = Object.assign({}, state.decisions, dec);
            return out.results;
        }

        _system(invSnow, invLift, invAccess) {
            const K = this.K;
            return {
                cov: Math.min(K.covMax, 0.38 + K.covPerM * invSnow),
                rate: 1 + K.ratePerM * invSnow,
                nights: Math.min(K.nightsMax, 1 + K.nightsPerM * invSnow),
                eff: 1 + K.effPerM * invSnow,
                liftCap: K.liftBase + K.liftPerM * Math.min(invLift, K.liftKnee) + K.liftPerMHigh * Math.max(0, invLift - K.liftKnee),
                accessCap: K.accessBase + K.accessPerM * invAccess,
                clearing: Math.min(K.clearMax, K.clearPerM * invAccess)
            };
        }

        _passDemand(price) {
            const K = this.K;
            return Math.max(0, Math.round(K.passQ * (1 - K.passSlope * (price - K.passRef) / K.passRef)));
        }

        _crowd(load) { return load <= 0.85 ? 0 : 7.5 * Math.pow(load - 0.85, 1.6); }

        // One type of day (peak or off-peak): demand, what binds, what is served.
        _dayType(o) {
            const K = this.K;
            const tickets = o.base * Math.exp(-o.el * (o.price / o.ref - 1)) * Math.pow(o.open, 0.85) * o.dem * o.boost * o.wom;
            const passes = o.passSold * o.pv * Math.pow(o.open, 0.5) * o.dem;
            const demand = tickets + passes;
            const comfort = o.liftCap * (0.30 + 0.70 * o.capOpen) * o.service + o.extraCap;
            const limits = [['demand', demand], ['lift', K.over * comfort], ['road', o.accessCap]];
            if (o.cap) limits.push(['cap', o.cap]);
            let lim = limits[0];
            for (let i = 1; i < limits.length; i++) if (limits[i][1] < lim[1]) lim = limits[i];
            const served = lim[1];
            const passServed = Math.min(passes, served);
            return { demand: demand, served: served, limit: lim[0], load: comfort > 0 ? served / comfort : 0, tickets: served - passServed, passVisits: passServed, comfort: comfort, arrivals: Math.min(demand, o.cap || demand) };
        }

        _computeRound(p, c, dec, wx, noVerdict) {
            const K = this.K, P = this.PERIODS[p];
            const r = { period: p, skierDays: 0, revenue: 0, cost: 0, ebitda: 0, cumEbitda: 0 };
            const rev = { passes: 0, tickets: 0, packs: 0, anc: 0 };
            const cost = { fixed: K.fixedMonth * P.months, staff: 0, ops: 0, visits: 0, snow: 0, extras: 0, om: 0 };

            if (p === 1) {
                const sys = this._system(dec.sbInvSnow, dec.sbInvLift, dec.sbInvAccess);
                c.invSnow = dec.sbInvSnow; c.invLift = dec.sbInvLift; c.invAccess = dec.sbInvAccess;
                c.cov = sys.cov; c.rate = sys.rate; c.nights = sys.nights; c.eff = sys.eff; c.liftCap = sys.liftCap; c.accessCap = sys.accessCap; c.clearing = sys.clearing;
                c.passPrice = dec.sbPassPrice; c.staff = dec.sbStaff;
                c.passSold = this._passDemand(dec.sbPassPrice);
                rev.passes = c.passSold * c.passPrice;
                cost.staff = c.staff * K.staffHire;
                cost.om = (dec.sbInvSnow + dec.sbInvLift + dec.sbInvAccess) * 1e6 * K.omRate;
                cost.extras = c.fc ? K.forecastCost : 0;
                r.passSold = c.passSold; r.invested = Math.round((dec.sbInvSnow + dec.sbInvLift + dec.sbInvAccess) * 10) / 10;
                r.openTerrain = 0; r.reservoir = c.water;
            } else {
                // 1 · snowmaking: only in cold nights, only with water, only where there are guns
                const req = (p === 2 ? dec.sbSnowDays : (p === 3 ? dec.sbSnowDaysJan : (p === 4 ? dec.sbSnowDaysFeb : 0))) || 0;
                const thaw = (p === 4 && wx.thaw) ? 1 : 0;
                const meltP = Math.min(0.85, wx.melt[p] + (thaw ? K.thawMelt : 0));
                const melted = c.made * (1 - meltP);
                const unitArea = this.UNIT * c.eff * (1 - K.yieldLoss * wx.melt[p]);
                const caps = [['request', req], ['coverage', Math.max(0, (c.cov - melted) / unitArea)], ['water', c.water], ['cold', wx.cold[p] * c.nights * c.rate]];
                let sl = caps[0];
                for (let i = 1; i < caps.length; i++) if (caps[i][1] < sl[1] - 1e-9) sl = caps[i];
                const prod = Math.max(0, sl[1]), snowLimit = sl[0];
                c.water = Math.round((c.water - prod) * 100) / 100;
                c.made = Math.min(c.cov, melted + prod * unitArea);
                const unitCost = K.snowCost * (wx.hard ? wx.hard[p] : 1) * (1 - K.snowSave * Math.min(c.invSnow, 6.2));
                cost.snow = prod * unitCost + (req > 0 ? K.snowStandby : 0);
                c.snowSpend += cost.snow;

                // 2 · terrain: natural cover from the top down, machine-made from the bottom up
                const nat = Math.max(0.10, wx.nat[p] - (thaw ? K.thawNat : 0));
                const open = Math.min(1, nat + c.made * Math.min(1, (1 - nat) / c.cov));
                c.open = open;

                // 3 · the two day types
                const sectors = (p === 3) ? dec.sbSectorsJan : 4;
                const openOff = open * (sectors / 4);
                const staffEff = c.staff + ((p === 2 && dec.sbExtraStaffDec) ? K.xmasStaffHeads : 0);
                let pricePeak = P.ref, priceOff = P.ref, boostOff = 1, capDay = 0, extraCap = 0;
                if (p === 2) { pricePeak = priceOff = dec.sbPriceDec; }
                if (p === 3) { pricePeak = dec.sbPriceWknd; priceOff = dec.sbPriceMid; boostOff = 1 + K.packLift * dec.sbPacks - 0.005 * dec.sbPacks * (dec.sbPacks - 1); }
                if (p === 4) { pricePeak = K.febPeakRef * (1 + dec.sbPeak / 100); priceOff = K.febOffPrice; capDay = dec.sbCap * 1000; extraCap = dec.sbHighSector ? K.highCap : 0; }
                if (p === 5) { pricePeak = priceOff = K.aprilPrice; }
                const qf = (p === 4 && dec.sbQueue) ? 1.04 : 1;
                const wom = this._clamp(1 + K.womSlope * (c.sat - K.satStart), 0.8, 1.1);

                const mk = (isPeak) => {
                    const o = {
                        base: isPeak ? P.basePeak : P.baseOff, ref: isPeak ? P.ref : (P.refOff || P.ref), price: isPeak ? pricePeak : priceOff,
                        el: isPeak ? P.elPeak : P.elOff, open: open, capOpen: isPeak ? open : openOff, dem: wx.dem[p], boost: isPeak ? 1 : boostOff * (1 - K.sectorDem + K.sectorDem * sectors / 4), wom: wom,
                        passSold: c.passSold, pv: isPeak ? P.pvPeak : P.pvOff, liftCap: c.liftCap * qf, accessCap: c.accessCap,
                        cap: isPeak ? capDay : 0, extraCap: extraCap * (isPeak ? 1 : 0.6), service: 1
                    };
                    const probe = this._dayType(o);
                    const needed = 140 + 120 * o.capOpen + 0.011 * Math.min(probe.demand, o.accessCap, o.cap || probe.demand);
                    o.service = this._clamp(staffEff / needed, 0.4, 1);
                    const out = this._dayType(o);
                    out.service = o.service; out.price = o.price; out.needed = needed;
                    return out;
                };
                const peak = mk(true), off = mk(false);

                // storms close the road: only the guests already in the valley ski
                const lost = wx.storm[p] * (1 - c.clearing);
                const lostPeak = Math.min(P.peakDays, lost * 0.4), lostOff = Math.min(P.offDays, lost * 0.6);
                const dPeak = P.peakDays - lostPeak * (1 - K.stormGuests), dOff = P.offDays - lostOff * (1 - K.stormGuests);

                const visits = peak.served * dPeak + off.served * dOff;
                const tkPeak = peak.tickets * dPeak * peak.price * K.yieldF;
                let tkOff = off.tickets * dOff * off.price * K.yieldF;
                if (p === 3 && dec.sbPacks > 0) {
                    const share = 1 - 1 / boostOff;
                    rev.packs = tkOff * share * K.packNet; tkOff = tkOff * (1 - share);
                }
                rev.tickets = tkPeak + tkOff;
                const svc = (peak.service * peak.served * dPeak + off.service * off.served * dOff) / Math.max(1, visits);
                const spill = 1 - K.ancCrowd * Math.max(0, peak.load - 0.95);
                rev.anc = (peak.served * dPeak * spill + off.served * dOff) * K.ancRev * (0.7 + 0.3 * svc);

                cost.staff = c.staff * K.staffMonth * P.months * (p === 5 ? 0.63 : 1);
                cost.ops = K.opsSector * 4 * P.sectorMonths * (0.45 + 0.55 * open) - (4 - sectors) * K.sectorSave + K.inSeasonFixed * P.months * (p === 5 ? 0.63 : 1);
                cost.visits = visits * K.varVisit + rev.anc * K.ancCogs;
                if (p === 2 && dec.sbExtraStaffDec) cost.extras += K.xmasStaffCost;
                if (p === 3) cost.extras += dec.sbPacks * K.packCost;
                if (p === 4) cost.extras += (dec.sbHighSector ? K.highCost : 0) + (dec.sbQueue ? K.queueCost : 0);

                // 4 · what the customer lived through
                const openSeen = (open * peak.served * dPeak + openOff * off.served * dOff) / Math.max(1, visits);
                const sd = {
                    terrain: this._clamp(2.0 * (openSeen - P.expOpen), -1.2, 1.2),
                    crowd: -this._crowd(peak.load) * ((p === 4 && dec.sbQueue) ? 0.6 : 1),
                    service: -3.0 * (1 - peak.service),
                    road: -Math.min(1.2, 4 * Math.max(0, peak.arrivals / c.accessCap - 0.85)) - 0.12 * lost,
                    price: 0
                };
                if (p === 4) sd.price = -1.2 * Math.max(0, dec.sbPeak / 100 - 0.15) - 1.5 * Math.max(0, (peak.demand - peak.served) / Math.max(1, peak.demand)) * (peak.limit === 'cap' ? 1 : 0.5);
                if (p === 2) sd.price = -0.03 * Math.max(0, dec.sbPriceDec - 55);
                if (p === 3) sd.price = -0.03 * Math.max(0, dec.sbPriceWknd - 60);
                const x = this._clamp(K.satBase + sd.terrain + sd.crowd + sd.service + sd.road + sd.price, 1, 10);
                const before = c.sat;
                c.sat = this._clamp(c.sat + P.w * (x - c.sat), 1, 10);

                c.peakRev += tkPeak + peak.served * dPeak * K.ancRev;
                c.seasonRev += rev.tickets + rev.packs + rev.anc;
                c.natW += P.w * nat;
                r.skierDays = Math.round(visits);
                r.openTerrain = Math.round(open * 100);
                r.reservoir = c.water;
                r.wx = { cold: wx.cold[p], nat: Math.round(nat * 100), storm: wx.storm[p], lost: Math.round(lost * 10) / 10, thaw: thaw };
                r.snow = { req: req, prod: Math.round(prod * 100) / 100, limit: snowLimit, made: Math.round(c.made * 100), cov: Math.round(c.cov * 100), unit: Math.round(unitCost) };
                r.peak = { demand: Math.round(peak.demand), served: Math.round(peak.served), limit: peak.limit, load: Math.round(peak.load * 100), price: Math.round(peak.price * 100) / 100, service: Math.round(peak.service * 100), staff: staffEff, needed: Math.round(peak.needed) };
                r.off = { demand: Math.round(off.demand), served: Math.round(off.served), limit: off.limit, load: Math.round(off.load * 100), price: Math.round(off.price * 100) / 100 };
                r.satParts = { x: Math.round(x * 10) / 10, terrain: Math.round(sd.terrain * 100) / 100, crowd: Math.round(sd.crowd * 100) / 100, service: Math.round(sd.service * 100) / 100, road: Math.round(sd.road * 100) / 100, price: Math.round(sd.price * 100) / 100, before: Math.round(before * 10) / 10 };

                if (p === 5) this._summer(c, dec, rev, cost, r);
            }

            const revenue = rev.passes + rev.tickets + rev.packs + rev.anc + (rev.summer || 0);
            const total = cost.fixed + cost.staff + cost.ops + cost.visits + cost.snow + cost.extras + cost.om + (cost.summer || 0);
            const ebitda = revenue - total;
            c.rev += revenue; c.ebitda += ebitda; c.cash += ebitda; c.skier += r.skierDays;

            r.revenue = Math.round(revenue); r.cost = Math.round(total); r.ebitda = Math.round(ebitda); r.cumEbitda = Math.round(c.ebitda);
            r.satisfaction = Math.round(c.sat * 10) / 10;
            r.cash = Math.round(c.cash);
            r.rev = {}; r.costs = {};
            Object.keys(rev).forEach(function (k) { r.rev[k] = Math.round(rev[k]); });
            Object.keys(cost).forEach(function (k) { r.costs[k] = Math.round(cost[k]); });
            if (p === 5 && !noVerdict) r.final = this._verdict(c, wx);
            return { c: c, results: r };
        }

        // April also closes the fiscal year: five more months of fixed cost, and the summer decision.
        _summer(c, dec, rev, cost, r) {
            const K = this.K;
            const opt = dec.sbSummer;
            c.summer = opt; c.risk = dec.sbRisk;
            cost.summer = K.fixedMonth * K.summerMonths;
            const liftSynergy = c.invLift >= 2 ? 1.15 : 1;
            const brand = this._clamp(0.85 + 0.06 * (c.sat - 6.5), 0.7, 1.1);
            let y1 = 0, mature = 0, capex = 0;
            if (opt >= 1) { y1 += K.bikeY1 * liftSynergy * brand; mature += K.bikeMature * liftSynergy * brand; capex += 1400000; }
            if (opt >= 2) { y1 += K.congressY1; mature += K.congressMature * brand; capex += 1700000; }
            rev.summer = Math.max(0, y1);
            cost.summer += Math.max(0, -y1) + capex * K.omRate;
            c.fiveYear = Math.round(y1 + 4 * mature - 5 * capex * K.omRate - capex);
            r.summer = { option: opt, year1: Math.round(y1 - capex * K.omRate), capex: capex, fiveYear: c.fiveYear };
        }

        // The three exposures the season revealed, and whether the declared risk matches them.
        _exposures(c) {
            const season = Math.max(1, c.seasonRev || 0);
            const snow = this._clamp((0.80 - (c.natW || 0)) / 0.40, 0, 1);
            const demand = this._clamp((c.peakRev / season - 0.50) / 0.25, 0, 1);
            const costx = this._clamp((c.snowSpend / season - 0.02) / 0.035, 0, 1);
            return { snow: Math.round(snow * 100) / 100, demand: Math.round(demand * 100) / 100, cost: Math.round(costx * 100) / 100 };
        }

        _par(wx, upTo) {
            let c = this._clone(this._seed(null, { wx: wx }).c);
            for (let p = 1; p <= (upTo || 5); p++) c = this._computeRound(p, c, this.PAR_PLAN[p], wx, true).c;
            return c.ebitda;
        }

        // Score and verdict always agree: the tier fixes the band, the quality of play places the run inside it.
        _composite(lo, span, q) { return Math.round(this._clamp(lo + span * this._clamp(q, 0, 1), 0, 100)); }

        // upTo < 5 gives the running verdict: par to date, and the board target is only judged at the close.
        _verdict(c, wx, upTo) {
            const K = this.K, last = !upTo || upTo >= 5, a = c.ebitda / this.TARGET;
            const par = wx ? this._par(wx, upTo) : this.TARGET;
            const ratio = par > 0 ? c.ebitda / par : (c.ebitda > 0 ? 1.3 : 0);
            const ex = this._exposures(c);
            const order = ['snow', 'demand', 'cost'].sort(function (m, n) { return ex[n] - ex[m]; });
            const riskFit = c.risk === order[0] ? 1 : (c.risk === order[1] ? 0.5 : 0);
            const renew = this._clamp(K.renewBase + K.renewSlope * (c.sat - K.satStart), 0.12, 0.62);
            let tier, lo, span, e;
            if (ratio >= 0.98 && (a >= 1 || !last) && c.sat >= 7) { tier = 'A'; lo = 85; span = 15; e = this._clamp((ratio - 0.98) / 0.15, 0, 1); }
            else if (ratio >= 0.92)                 { tier = 'B'; lo = 70; span = 14; e = this._clamp((ratio - 0.92) / 0.13, 0, 1); }
            else if (ratio >= 0.78)                 { tier = 'C'; lo = 50; span = 19; e = this._clamp((ratio - 0.78) / 0.14, 0, 1); }
            else                                    { tier = 'D'; lo = 15; span = 34; e = this._clamp((ratio - 0.2) / 0.58, 0, 1); }
            const s = this._clamp((c.sat - 5) / 3.5, 0, 1);
            const f = this._clamp((c.fiveYear || 0) / K.fiveYearRef, 0, 1);
            const q = 0.5 * e + 0.25 * s + 0.15 * f + 0.10 * riskFit;
            return {
                tier: tier, score: this._composite(lo, span, q), attainment: Math.round(a * 100), par: Math.round(par), parRatio: Math.round(ratio * 100), metTarget: a >= 1 ? 1 : 0, renewRate: Math.round(renew * 100),
                renewals: Math.round(c.passSold * renew), renewValue: Math.round(c.passSold * renew * c.passPrice),
                exposures: ex, topRisk: order[0], declared: c.risk, riskFit: riskFit, water: c.water
            };
        }

        // ── forecast ─────────────────────────────────────────────────────
        _natDays(nat) {
            let d = 0;
            for (let p = 2; p <= 5; p++) d += (this.PERIODS[p].peakDays + this.PERIODS[p].offDays) * this._clamp((nat[p] - 0.15) / 0.70, 0, 1);
            return Math.round(d);
        }

        _outlook(ds) {
            const K = this.K, bought = !!(ds.c && ds.c.fc), sig = ds.wx.signal;
            const rows = [], miss = (1 - K.fcAccuracy) / 3;
            let sum = 0;
            this.TYPES.forEach((t) => {
                const a = this.ARCH[t];
                const w = bought ? a.prob * (t === sig ? K.fcAccuracy : miss) : a.prob;
                sum += w;
                rows.push({ type: t, w: w, natDays: this._natDays(a.nat), coldDec: a.cold[2], natDec: a.nat[2] });
            });
            let eDays = 0, eCold = 0, lowDec = 0, loD = 999, hiD = 0, loC = 999, hiC = 0;
            rows.forEach(function (x) {
                x.p = x.w / sum;
                eDays += x.p * x.natDays; eCold += x.p * x.coldDec;
                if (x.natDec < 0.35) lowDec += x.p;
                if (x.p >= K.rangeFloor) { loD = Math.min(loD, x.natDays); hiD = Math.max(hiD, x.natDays); loC = Math.min(loC, x.coldDec - 2); hiC = Math.max(hiC, x.coldDec + 2); }
            });
            return { bought: bought, signal: sig, rows: rows, eDays: Math.round(eDays), eCold: Math.round(eCold), lowDec: lowDec, days: [loD, hiD], cold: [Math.max(0, loC), hiC] };
        }

        // ── hints, chart, table, summary ─────────────────────────────────
        _hintKey(state, res) {
            const p = res.period, d = state.decisions || {};
            const num = function (v) { return parseFloat(v) || 0; };
            if (p === 1) {
                if (num(d.sbInvSnow) >= 3) return 'hint_water_binds';
                if (num(d.sbInvLift) >= 3 && num(d.sbInvSnow) < 1) return 'hint_lift';
                if (num(d.sbInvAccess) >= 3) return 'hint_access';
                if (num(d.sbPassPrice) >= 660) return 'hint_pass_high';
                if (num(d.sbPassPrice) <= 440) return 'hint_pass_low';
                return 'hint_p1';
            }
            if (p === 5) return 'hint_p5';
            if (p === 4 && res.wx.thaw && res.reservoir < 1 && res.snow.prod < 1) return 'hint_no_water';
            if (res.snow.limit === 'cold' && res.snow.req - res.snow.prod >= 1) return 'hint_cold';
            if (res.peak.service < 90) return 'hint_staff';
            if (p === 4 && res.peak.staff > res.peak.needed * 1.12) return 'hint_overstaff';
            if (p === 2) {
                if (res.openTerrain < 40) return 'hint_terrain';
                if (res.peak.limit === 'lift') return 'hint_discount';
                if (res.reservoir <= 1) return 'hint_reservoir';
                return 'hint_p2';
            }
            if (p === 3) {
                if (res.peak.limit === 'lift') return 'hint_discount';
                if (res.off.load < 30 && num(d.sbSectorsJan) === 4) return 'hint_sectors';
                return 'hint_p3';
            }
            if (res.peak.load > 105) return 'hint_saturation';
            if (res.peak.limit === 'cap' && res.peak.load < 85) return 'hint_cap_low';
            if (res.peak.limit === 'road') return 'hint_road';
            return 'hint_p4';
        }
        getHint(state, results) {
            try { return this._t(this._hintKey(state, results)); } catch (e) { return null; }
        }

        getChartConfig() {
            return {
                sbChart: {
                    type: 'bar',
                    data: { labels: [], datasets: [
                        { label: 'EBITDA', data: [], backgroundColor: '#1f6f9e', order: 2, yAxisID: 'y' },
                        { label: '%', data: [], type: 'line', borderColor: '#a9540f', backgroundColor: 'transparent', borderWidth: 2, tension: 0.3, order: 1, yAxisID: 'y1' }
                    ] },
                    options: {
                        plugins: { legend: { position: 'bottom' } },
                        scales: {
                            y:  { position: 'left',  title: { display: true, text: '€' } },
                            y1: { position: 'right', min: 0, max: 100, grid: { drawOnChartArea: false }, title: { display: true, text: '%' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const h = (state && Array.isArray(state.history)) ? state.history : [];
            const rs = h.map(function (x) { return (x && x.results) ? x.results : {}; });
            return { sbChart: {
                labels: rs.map((x) => this._t('ms' + (x.period || 1))),
                datasets: [
                    { label: this._t('chEbitda'), data: rs.map(function (x) { return x.ebitda || 0; }) },
                    { label: this._t('chTerrain'), data: rs.map(function (x) { return x.openTerrain || 0; }) }
                ]
            } };
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period',       label: this._t('hMonth'),   formatter: (v) => this._t('ms' + (v || 1)) },
                { key: 'results.skierDays',    label: this._t('hSkier'),   formatter: (v) => this._n(v || 0) },
                { key: 'results.openTerrain',  label: this._t('hTerrain'), formatter: (v) => (v || 0) + ' %' },
                { key: 'results.reservoir',    label: this._t('hWater'),   formatter: (v) => this._n(v || 0, 1) },
                { key: 'results.revenue',      label: this._t('hRev'),     formatter: (v) => this._eur(v || 0) },
                { key: 'results.ebitda',       label: this._t('hEbitda'),  formatter: (v) => this._eur(v || 0) },
                { key: 'results.satisfaction', label: this._t('hSat'),     formatter: (v) => this._n(v || 0, 1) }
            ];
        }

        getPerformanceSummary(history) {
            const h = Array.isArray(history) ? history : [];
            const last = h.length ? (h[h.length - 1].results || {}) : {};
            const st = this._state();
            const c = (st && st.domainState && st.domainState.c) ? st.domainState.c : null;
            const v = last.final || (c ? this._verdict(c, st.domainState.wx) : { tier: 'D', score: 0, attainment: 0, par: 0, parRatio: 0, metTarget: 0, renewRate: 0, renewals: 0, renewValue: 0, exposures: {}, topRisk: 'snow', declared: 'snow', riskFit: 0, water: 0 });
            const wxType = (st && st.domainState && st.domainState.wx) ? st.domainState.wx.type : 'B';
            const key = 'tier_' + v.tier.toLowerCase();
            const ins = [];
            ins.push(this._t(v.metTarget ? 'ins_target_ok' : 'ins_target_no', { v: this._meur(last.cumEbitda || 0), t: this._meur(this.TARGET), a: v.attainment }));
            ins.push(this._t('ins_winter', { w: this._t('wx' + wxType), d: this._t('wx' + wxType + 'd') }));
            ins.push(this._t('ins_par', { p: this._meur(v.par || 0), r: v.parRatio || 0 }));
            ins.push(this._t('ins_sat', { v: this._n(last.satisfaction || 0, 1), r: v.renewRate, n: this._n(v.renewals), e: this._meur(v.renewValue) }));
            if (v.water >= 3) ins.push(this._t('ins_water_left', { v: this._n(v.water, 1) }));
            if (last.summer) ins.push(this._t('ins_summer' + last.summer.option, { y: this._eur(last.summer.year1), f: this._meur(last.summer.fiveYear) }));
            ins.push(this._t(v.riskFit === 1 ? 'ins_risk_ok' : 'ins_risk_off', { d: this._t('risk_' + v.declared), t: this._t('risk_' + v.topRisk) }));
            ins.push(this._t('ins_transfer'));
            return {
                totalPeriods: h.length, performance: v.tier, performanceKey: key, performanceLabel: this._t(key),
                composite: v.score, overallScore: v.score, totalScore: v.score, score: v.score,
                message: this._t('sum_score', { s: v.score }), insights: ins
            };
        }

        formatCompletionMessage(summary) { return super.formatCompletionMessage(summary); }

        // ── UI ───────────────────────────────────────────────────────────
        _later() {
            setTimeout(() => { try { this._render(); } catch (e) { } }, 30);
        }

        _bindRepaint() {
            if (this._bound) return;
            this._bound = true;
            const repaint = () => {
                try { this._render(); } catch (e) { }
                try { const s = this._sim(); if (s) { s.updateCharts(); s.renderHistoryTable(); } } catch (e) { }
                try { this._repaintModal(); } catch (e) { }
            };
            try { document.addEventListener('express:langchanged', repaint); } catch (e) { }
            try {
                const s = this._sim();
                if (s && s.eventBus && typeof s.eventBus.on === 'function') {
                    s.eventBus.on('language:changed', repaint);
                    s.eventBus.on('period:submitted', repaint);
                    s.eventBus.on('period:undone', () => { this._syncControlsFromDecisions(); repaint(); });
                }
            } catch (e) { }
        }

        // The framework fills its completion modal once; keep it in step with the language.
        _repaintModal() {
            const st = this._state();
            const box = document.getElementById('usf-completion-content') || document.getElementById('completionContent');
            if (!st || !box || !this._done(st) || !box.innerHTML) return;
            box.innerHTML = this.formatCompletionMessage(this.getPerformanceSummary(st.history || []));
        }

        _wire() {
            const box = document.querySelector('.sb2063-container');
            if (box && !box._sbWired) {
                box._sbWired = true;
                const onInput = (ev) => {
                    try {
                        const t = ev && ev.target;
                        const st = this._state();
                        if (t && t.type === 'number' && ev.type === 'change') t.value = String(this._num(t.id, parseFloat(t.getAttribute('value')) || 0));
                        if (t && t.id && st && t.id.indexOf('sb') === 0) {
                            if (!st.decisions || Array.isArray(st.decisions)) st.decisions = this._decObj(st.decisions);
                            st.decisions[t.id] = (t.type === 'checkbox') ? (t.checked ? 1 : 0) : t.value;
                        }
                        this._readouts();
                    } catch (e) { }
                };
                box.addEventListener('input', onInput);
                box.addEventListener('change', onInput);
            }
            const buy = this._el('sbBuyForecast');
            if (buy && !buy._sbWired) {
                buy._sbWired = true;
                buy.addEventListener('click', () => this._buyForecast());
            }
        }

        _buyForecast() {
            const st = this._state();
            if (!st || this._period(st) !== 1 || this._locked(st)) return;
            const ds = st.domainState;
            if (ds.c.fc) return;
            ds.c.fc = 1;
            if (ds.at && ds.at[1]) ds.at[1].fc = 1;
            if (!st.decisions || Array.isArray(st.decisions)) st.decisions = this._decObj(st.decisions);
            st.decisions.sbBuyForecast = 1;
            try { st.persist(2); } catch (e) { }
            this._render();
        }

        _syncControlsFromDecisions() {
            const st = this._state();
            if (!st || !st.decisions) return;
            Object.keys(st.decisions).forEach((id) => {
                const e = this._el(id);
                if (!e || id === 'sbBuyForecast') return;
                if (e.type === 'checkbox') e.checked = (st.decisions[id] === 1 || st.decisions[id] === true || st.decisions[id] === '1');
                else e.value = st.decisions[id];
            });
        }

        _locked(st) {
            const p = parseInt(st.currentPeriod, 10) || 1;
            return (st.history || []).some(function (x) { return x && parseInt(x.period, 10) === p; });
        }
        _done(st) {
            try { const s = this._sim(); if (s && typeof s.isRunComplete === 'function' && s.isRunComplete()) return true; } catch (e) { }
            return (st.history || []).some(function (x) { return x && parseInt(x.period, 10) >= 5; });
        }

        _set(id, txt) { const e = this._el(id); if (e) e.textContent = txt; }
        _bar(id, frac) { const e = this._el(id); if (e) e.style.width = (this._clamp(frac, 0, 1) * 100) + '%'; }
        _show(id, on, cls) { const e = this._el(id); if (e) e.classList.toggle(cls || 'sb2063-on', !!on); }

        _readouts() {
            const pairs = [['sbInvSnow', 1], ['sbInvLift', 1], ['sbInvAccess', 1], ['sbSnowDays', 1], ['sbSnowDaysJan', 1], ['sbSnowDaysFeb', 1], ['sbPacks', 0], ['sbCap', 1], ['sbPeak', 0]];
            pairs.forEach((x) => {
                const i = this._el(x[0]), o = this._el(x[0] + 'Out');
                if (i && o) o.textContent = this._n(parseFloat(i.value) || 0, x[1]);
            });
            const st = this._state();
            const box = this._el('sbBudget');
            if (box) {
                const total = this._invTotal(), left = this.BUDGET - total;
                box.textContent = this._t('budgetLabel', { used: this._n(total, 1), left: this._n(left, 1) });
                box.classList.toggle('sb2063-over', left < -1e-9);
            }
            if (st && st.domainState && st.domainState.wx) { this._sysPreview(st); this._snowNotes(st); }
        }

        _sysPreview(st) {
            const box = this._el('sbSysPreview');
            if (!box) return;
            const s = this._system(this._num('sbInvSnow', 0), this._num('sbInvLift', 0), this._num('sbInvAccess', 0));
            const o = this._outlook(st.domainState), k = s.rate * s.nights;
            const lo = Math.min(this.WATER0, o.cold[0] * k), hi = Math.min(this.WATER0, o.cold[1] * k);
            const lo0 = Math.min(this.WATER0, o.cold[0]), hi0 = Math.min(this.WATER0, o.cold[1]);
            let html = this._t('sys_snow', { k: this._n(k, 1), f: this._n((s.eff - 1) * 100), c1: this._n(s.cov * 100), w: this._n(this.WATER0) });
            if (k >= 2) html += ' <span class="sb2063-flag">' + this._t('sys_water_flag') + '</span>';
            html += '<br>' + this._t('sys_dec', { a: o.cold[0], b: o.cold[1], lo: this._n(lo, 1), hi: this._n(hi, 1), lo0: this._n(lo0, 1), hi0: this._n(hi0, 1) });
            html += '<br>' + this._t('sys_lift', { v: this._n(s.liftCap) }) + ' · ' + this._t('sys_access', { v: this._n(s.accessCap), k: this._n(s.clearing * 100) });
            html += '<br>' + this._t('sys_pass', { n: this._n(this._passDemand(this._num('sbPassPrice', 560))), v: this._meur(this._passDemand(this._num('sbPassPrice', 560)) * this._num('sbPassPrice', 560)) });
            box.innerHTML = html;
        }

        _snowNotes(st) {
            const c = st.domainState.c, wx = st.domainState.wx;
            [[2, 'sbSnowDays', 'sbSnowNote2'], [3, 'sbSnowDaysJan', 'sbSnowNote3'], [4, 'sbSnowDaysFeb', 'sbSnowNote4']].forEach((x) => {
                const sl = this._el(x[1]), note = this._el(x[2]);
                if (sl) {
                    const mx = Math.floor(c.water * 2) / 2;
                    sl.setAttribute('max', String(mx)); sl.max = String(mx);
                    if (parseFloat(sl.value) > mx) sl.value = String(mx);
                }
                if (note) {
                    const f = wx.fcC[x[0]];
                    note.textContent = this._t('snow_note', { w: this._n(c.water, 1), a: f[0], b: f[1], lo: this._n(Math.min(c.water, f[0] * c.rate * c.nights), 1), hi: this._n(Math.min(c.water, f[1] * c.rate * c.nights), 1), m: this._n(c.made * 100), e: this._n(c.cov * 100) });
                }
            });
        }

        _render() {
            const st = this._state();
            if (!st || !st.domainState || !st.domainState.c) return;
            const ds = st.domainState, c = ds.c;
            const done = this._done(st), p = this._period(st), locked = !done && this._locked(st);

            this.PANELS.forEach((id, i) => this._show(id, !done && !locked && i === p - 1));
            this._show('sbActions', done || locked, 'sb2063-off');
            this._set('sbMonth', this._t('m' + p));

            this._set('sbTerrain', p === 1 && !done ? '—' : this._pct(c.open)); this._bar('sbTerrainBar', c.open);
            this._set('sbRes', this._t('water_val', { v: this._n(c.water, 1) })); this._bar('sbResBar', c.water / this.WATER0);
            this._set('sbMade', this._t('made_val', { m: this._n(c.made * 100), e: this._n(c.cov * 100) })); this._bar('sbMadeBar', c.made / Math.max(0.01, c.cov));
            this._set('sbSat', this._n(c.sat, 1)); this._bar('sbSatBar', c.sat / 10);
            this._set('sbSkier', this._n(c.skier));
            this._set('sbRev', this._meur(c.rev));
            this._set('sbEbitda', this._meur(c.ebitda));
            const eb = this._el('sbEbitda'); if (eb) eb.classList.toggle('sb2063-neg', c.ebitda < 0);
            this._set('sbTarget', this._meur(this.TARGET));

            const brief = this._el('sbBrief');
            if (brief) brief.innerHTML = done ? this._t('brief_done') : (locked ? this._t('brief_wait') : this._t('brief' + p));

            this._renderWx(st, p, done);
            this._readouts();
            this._renderReport(st);
            this._renderFinal(st, done);
            const cv = this._el('sbChart'); if (cv) cv.setAttribute('aria-label', this._t('chAria'));
        }

        _renderWx(st, p, done) {
            const ds = st.domainState, wx = ds.wx, title = this._el('sbWxTitle'), body = this._el('sbWxBody');
            if (!title || !body) return;
            this._show('sbWxCard', true);
            let html = '';
            if (done || p === 5) {
                title.textContent = this._t('wx_title_end');
                html += '<p>' + this._t('wx_end', { w: '<b>' + this._t('wx' + wx.type) + '</b>', d: this._t('wx' + wx.type + 'd') }) + '</p>';
            } else if (p === 1) {
                const o = this._outlook(ds);
                title.textContent = this._t(o.bought ? 'wx_title_paid' : 'wx_title_public');
                html += '<p>' + this._t(o.bought ? 'wx_intro_paid' : 'wx_intro_public', { w: this._t('wx' + o.signal) }) + '</p>';
                o.rows.forEach((x) => {
                    html += '<div class="sb2063-wxrow"><span class="sb2063-wxname">' + this._t('wx' + x.type) + '</span>'
                        + '<span class="sb2063-wxbar"><i style="width:' + Math.round(x.p * 100) + '%"></i></span>'
                        + '<span class="sb2063-wxpct">' + Math.round(x.p * 100) + ' %</span>'
                        + '<span class="sb2063-wxfig">' + this._t('wx_fig', { d: x.natDays, c: x.coldDec }) + '</span></div>';
                });
                html += '<div class="sb2063-range">'
                    + '<span class="sb2063-chip">' + this._t('wx_chip_days') + '<b>' + o.days[0] + ' – ' + o.days[1] + '</b>' + this._t('wx_expected', { v: o.eDays }) + '</span>'
                    + '<span class="sb2063-chip">' + this._t('wx_chip_cold') + '<b>' + o.cold[0] + ' – ' + o.cold[1] + '</b>' + this._t('wx_expected', { v: o.eCold }) + '</span>'
                    + '<span class="sb2063-chip">' + this._t('wx_chip_xmas') + '<b>' + Math.round(o.lowDec * 100) + ' %</b></span></div>'
                    + '<p class="sb2063-note">' + this._t('wx_range_note') + '</p>';
            } else {
                title.textContent = this._t('wx_title_month', { m: this._t('m' + p) });
                // the warm spell is applied to natural cover after the draw, so the range must carry it too
                const fc = wx.fcC[p], shift = (p === 4 && wx.thaw) ? this.K.thawNat : 0;
                const fn = wx.fcN[p].map(function (v) { return shift ? Math.max(0.10, v - shift) : v; });
                const stormKey = wx.storm[p] >= 2 ? 'wx_storm_hi' : (wx.storm[p] === 1 ? 'wx_storm_mid' : 'wx_storm_lo');
                html += '<p>' + this._t('wx_month_intro') + '</p><div class="sb2063-range">'
                    + '<span class="sb2063-chip">' + this._t('wx_chip_coldm') + '<b>' + fc[0] + ' – ' + fc[1] + '</b></span>'
                    + '<span class="sb2063-chip">' + this._t('wx_chip_nat') + '<b>' + Math.round(fn[0] * 100) + ' – ' + Math.round(fn[1] * 100) + ' %</b></span>'
                    + '<span class="sb2063-chip">' + this._t('wx_chip_storm') + '<b>' + this._t(stormKey) + '</b></span>'
                    + (p === 4 ? '<span class="sb2063-chip">' + this._t('wx_chip_thaw') + '<b>' + this._t(wx.thaw ? 'wx_thaw_yes' : 'wx_thaw_no') + '</b></span>' : '') + '</div>';
                if (p === 2 || p === 3) html += '<p class="sb2063-note">' + this._t('wx_thaw_base') + '</p>';
            }
            const seen = (st.history || []).filter(function (x) { return x && x.results && x.results.wx; });
            if (seen.length && !(p === 1 && !done)) {
                html += '<h3>' + this._t('wx_seen') + '</h3>';
                seen.forEach((x) => {
                    const r = x.results;
                    html += '<div class="sb2063-rline"><span>' + this._t('m' + r.period) + '</span><b>' + this._t('wx_seen_line', { c: r.wx.cold, n: r.wx.nat, p: this._n(r.snow.prod, 1), o: r.openTerrain }) + '</b></div>';
                });
            }
            body.innerHTML = html;
            const bought = !!ds.c.fc;
            this._show('sbWxBuyRow', p === 1 && !done && !this._locked(st) && !bought);
        }

        _line(label, value, cls) { return '<div class="sb2063-rline' + (cls ? ' ' + cls : '') + '"><span>' + label + '</span><b>' + value + '</b></div>'; }
        _limit(k, hot) { return '<span class="sb2063-limit' + (hot ? ' sb2063-hot' : '') + '">' + this._t('lim_' + k) + '</span>'; }

        _renderReport(st) {
            const box = this._el('sbReport');
            if (!box) return;
            const h = st.history || [];
            const rec = h.length ? h[h.length - 1] : null;
            const r = rec && rec.results ? rec.results : null;
            if (!r || !r.costs) { this._show('sbReport', false); box.innerHTML = ''; return; }
            this._show('sbReport', true);
            let html = '<h2>' + this._t('rep_title', { m: this._t('m' + r.period) }) + '</h2><div class="sb2063-rgrid"><div>';
            if (r.period === 1) {
                html += this._line(this._t('rep_passes'), this._n(r.passSold));
                html += this._line(this._t('rep_invested'), this._n(r.invested, 1) + ' M€');
            } else {
                html += this._line(this._t('rep_cold'), this._n(r.wx.cold));
                html += this._line(this._t('rep_nat'), r.wx.nat + ' %');
                html += this._line(this._t('rep_snow'), this._t('rep_snow_val', { p: this._n(r.snow.prod, 1), q: this._n(r.snow.req, 1) }) + ' ' + this._limit('s_' + r.snow.limit, r.snow.limit === 'cold' || r.snow.limit === 'water'));
                html += this._line(this._t('rep_made'), this._t('made_val', { m: r.snow.made, e: r.snow.cov }));
                html += this._line(this._t('rep_open'), r.openTerrain + ' %');
                html += this._line(this._t('rep_peak'), this._t('rep_day_val', { s: this._n(r.peak.served), d: this._n(r.peak.demand), l: r.peak.load }) + ' ' + this._limit(r.peak.limit, r.peak.limit !== 'demand'));
                html += this._line(this._t('rep_off'), this._t('rep_day_val', { s: this._n(r.off.served), d: this._n(r.off.demand), l: r.off.load }) + ' ' + this._limit(r.off.limit, r.off.limit !== 'demand'));
                html += this._line(this._t('rep_staff'), this._t('rep_staff_val', { s: this._n(r.peak.staff), n: this._n(r.peak.needed) }));
                if (r.wx.lost > 0) html += this._line(this._t('rep_storm'), this._n(r.wx.lost, 1));
                if (r.wx.thaw) html += this._line(this._t('rep_thaw'), this._t('rep_thaw_val'));
                html += this._line(this._t('rep_sat'), this._t('rep_sat_val', { x: this._n(r.satParts.x, 1), a: this._n(r.satParts.before, 1), b: this._n(r.satisfaction, 1) }));
                const parts = ['terrain', 'crowd', 'service', 'road', 'price'].filter(function (k) { return Math.abs(r.satParts[k]) >= 0.05; });
                if (parts.length) html += this._line(this._t('rep_sat_why'), parts.map((k) => this._t('sp_' + k) + ' ' + (r.satParts[k] > 0 ? '+' : '') + this._n(r.satParts[k], 1)).join(' · '));
            }
            html += '</div><div>';
            if (r.rev.passes) html += this._line(this._t('rep_r_passes'), this._eur(r.rev.passes));
            if (r.rev.tickets) html += this._line(this._t('rep_r_tickets'), this._eur(r.rev.tickets));
            if (r.rev.packs) html += this._line(this._t('rep_r_packs'), this._eur(r.rev.packs));
            if (r.rev.anc) html += this._line(this._t('rep_r_anc'), this._eur(r.rev.anc));
            if (r.rev.summer) html += this._line(this._t('rep_r_summer'), this._eur(r.rev.summer));
            html += this._line(this._t('rep_c_fixed'), '−' + this._eur(r.costs.fixed + (r.costs.summer || 0)));
            if (r.costs.staff) html += this._line(this._t('rep_c_staff'), '−' + this._eur(r.costs.staff));
            if (r.costs.ops) html += this._line(this._t('rep_c_ops'), '−' + this._eur(r.costs.ops));
            if (r.costs.visits) html += this._line(this._t('rep_c_visits'), '−' + this._eur(r.costs.visits));
            if (r.costs.snow) html += this._line(this._t('rep_c_snow'), '−' + this._eur(r.costs.snow));
            if (r.costs.om) html += this._line(this._t('rep_c_om'), '−' + this._eur(r.costs.om));
            if (r.costs.extras) html += this._line(this._t('rep_c_extras'), '−' + this._eur(r.costs.extras));
            html += this._line(this._t('rep_ebitda'), this._eur(r.ebitda), 'sb2063-total');
            html += '</div></div>';
            html += '<div class="sb2063-coach">' + this._t(this._hintKey(rec, r)) + '</div>';
            box.innerHTML = html;
        }

        _renderFinal(st, done) {
            const box = this._el('sbFinal');
            if (!box) return;
            if (!done) { this._show('sbFinal', false); box.innerHTML = ''; return; }
            const sum = this.getPerformanceSummary(st.history || []);
            let html = '<p class="sb2063-tier">' + sum.performanceLabel + '</p><p class="sb2063-score">' + sum.message + '</p><ul>';
            sum.insights.forEach(function (x) { html += '<li>' + x + '</li>'; });
            box.innerHTML = html + '</ul>';
            this._show('sbFinal', true);
        }

